/* KshetraSetu — enhanced PS-complete prototype layer
   Preserves the existing UI and data-integrity rule: no fabricated government evidence.
*/
const STORE='ks_';
const load=(k,d)=>{try{return JSON.parse(localStorage.getItem(STORE+k)||JSON.stringify(d))}catch{return d}};
const state={
 page:'command',selectedParcel:'103',twinLayer:'recorded',offline:false,surveyStarted:false,currentPosition:null,geoWatch:null,gnssPort:null,
 fieldPoints:load('fieldPoints',[]),boundary:load('boundary',[]),boundaryHistory:[],boundaryFuture:[],pending:load('pending',[]),audit:load('audit',[]),notes:load('notes',[]),photos:load('photos',[]),controlPoints:load('controlPoints',[]),projects:load('projects',[{id:'KSS-RMP-2026-001',name:'Rampur Agricultural Resurvey — Phase I',location:'Rampur · Haveli Taluka · Pune District · Maharashtra',area:'36.4 ha',parcels:'20+',status:'82% Complete'}]),
 parcels:load('parcels',[{id:'101',area:'1.42',state:'verified',crop:'Sugarcane',delta:'0.3%',displacement:'0.21',confidence:'96.2'},{id:'102',area:'2.06',state:'pending',crop:'Wheat',delta:'-2.1%',displacement:'0.44',confidence:'93.5'},{id:'103',area:'1.82',state:'conflict',crop:'Soybean',delta:'-8.24%',displacement:'1.14',confidence:'91.7',newArea:'1.67',verifiedArea:'1.69'},{id:'104',area:'0.96',state:'verified',crop:'Vegetables',delta:'0.8%',displacement:'0.17',confidence:'97.1'},{id:'105',area:'2.31',state:'pending',crop:'Jowar',delta:'-1.4%',displacement:'0.31',confidence:'94.8'},{id:'106',area:'1.27',state:'verified',crop:'Onion',delta:'0.1%',displacement:'0.09',confidence:'98.3'},{id:'107',area:'1.74',state:'conflict',crop:'Cotton',delta:'-5.7%',displacement:'0.88',confidence:'89.6'}]),
 methodology:load('methodology',{}), importedGcp:load('importedGcp',[]), uavFile:null,loadedGeoJson:null,changeGeos:load('changeGeos',{}),recordEvidence:load('recordEvidence',null),geometryAnalysis:null,paperGcpPairs:load('paperGcpPairs',[]),paperGeoref:null
};
const app=document.getElementById('app');
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
function persist(){['fieldPoints','boundary','pending','audit','notes','photos','controlPoints','projects','parcels','methodology','importedGcp','changeGeos','paperGcpPairs','paperGeoref'].forEach(k=>localStorage.setItem(STORE+k,JSON.stringify(state[k])))}
function toast(msg){const d=document.createElement('div');d.className='toast';d.textContent=msg;document.body.appendChild(d);setTimeout(()=>d.remove(),3000)}
function audit(action,meta={}){state.audit.push({action,time:new Date().toISOString(),officer:'SURVEY-001',...meta});if(state.audit.length>500)state.audit=state.audit.slice(-500);persist()}
function status(s){const c=s==='verified'||s==='done'||s==='complete'?'green':s==='pending'?'amber':s==='conflict'||s==='fail'?'red':'blue';return `<span class="status ${c}">${esc(String(s).toUpperCase())}</span>`}
function login(){app.innerHTML=`<div class="login"><div class="login-card"><div class="brand"><div class="brandmark">KS</div><div><div class="eyebrow">SIH26010 · NATIONAL GEOSPATIAL PROTOTYPE</div><h1>KSHETRASETU</h1></div></div><h2>Agricultural Land Resurvey & Cadastral Verification Platform</h2><p class="sub">From Field Survey to Verified Digital Parcel.</p><div class="field"><label>OFFICER ID</label><input id="uid" value="SURVEY-001"></div><div class="field"><label>PASSWORD</label><input id="pw" type="password" value="demo123"></div><button class="btn primary" style="width:100%;padding:13px" onclick="doLogin()">Enter Command Center</button><div class="demo"><b>DEMO MODE</b><br>Officer ID: SURVEY-001 · Password: demo123</div><p class="sub" style="font-size:11px;margin-top:18px">Integration Ready — Requires Authorized Government APIs/Data Access</p></div></div>`}
function doLogin(){if(document.getElementById('uid').value==='SURVEY-001'&&document.getElementById('pw').value==='demo123')renderShell();else toast('Demo credentials do not match.')}
const nav=[['command','⌂','Command Center'],['twin','◈','Digital Parcel Twin'],['projects','▣','Survey Projects'],['method','≋','Survey Methodology'],['control','◎','Survey Control'],['field','⌖','Field Survey'],['uav','◇','UAV Workspace'],['ai','✦','AI Boundary Analysis'],['gis','⬡','GIS Validation'],['change','◫','Change Analysis'],['evidence','◌','Evidence & Audit'],['public','◉','Public Data']];
function renderShell(){app.innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="side-brand"><div class="brandmark" style="width:38px;height:38px">KS</div><strong>KSHETRASETU</strong><span>Field → Cadastral</span></div><nav class="nav">${nav.map(x=>`<button data-page="${x[0]}" onclick="go('${x[0]}')">${x[1]} <span>${x[2]}</span></button>`).join('')}</nav><div class="side-bottom">PUBLIC-SOURCE / LIVE INPUT MODE<br>Official verification required.</div></aside><main class="main"><header class="topbar"><div class="top-title" id="topTitle">Command Center</div><div class="top-actions"><span class="pill"><i class="dot"></i> ${state.offline?'OFFLINE CAPTURE':'PUBLIC DATA CONNECTED'}</span><span class="pill">SURVEY-001</span><button class="btn ghost" onclick="exportData()">Export</button></div></header><div class="content" id="content"></div></main></div>`;go(state.page)}
function go(p){state.page=p;document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));document.getElementById('topTitle').textContent=nav.find(x=>x[0]===p)?.[2]||'KshetraSetu';pages[p]();window.scrollTo(0,0)}
function head(title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">KSHETRASETU / ${esc(state.page)}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
function kpi(label,value,hint=''){return `<div class="card kpi"><div class="label">${label}</div><div class="value">${value}</div><div class="hint">${hint}</div></div>`}
function publicMap(id='publicMap',h=450){return `<div class="map-wrap"><div id="${id}" style="height:${h}px;width:100%;border-radius:12px"></div><div class="map-overlay-note">Public basemap: OpenStreetMap contributors. Parcel geometry is prototype/user-supplied evidence, not an official cadastral layer.</div></div>`}
function initMap(id,lat=18.5204,lon=73.8567,zoom=12){const el=document.getElementById(id);if(!el||typeof L==='undefined')return;const map=L.map(el,{zoomControl:true}).setView([lat,lon],zoom);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'}).addTo(map);setTimeout(()=>map.invalidateSize(),100);return map}
function parcelShapes(){const a=[['101','60,120 185,90 230,170 90,195'],['102','240,85 370,105 345,205 220,180'],['103','390,70 530,92 510,210 370,200'],['104','550,100 710,90 735,205 530,215'],['105','70,220 220,205 260,330 90,345'],['106','285,225 430,215 455,345 270,350'],['107','480,230 700,220 735,355 465,365']];return a.map(([id,pts])=>{const p=state.parcels.find(x=>x.id===id);return `<polygon class="parcel ${p.state} ${state.selectedParcel===id?'selected':''}" points="${pts}" onclick="selectParcel('${id}')"/><text x="${pts.split(' ')[0].split(',')[0]}" y="${Number(pts.split(' ')[0].split(',')[1])+22}" class="map-label" style="pointer-events:none">P-${id}</text>`}).join('')}
function selectParcel(id){state.selectedParcel=id;toast(`Parcel ${id} selected`);go('twin')}
function commandMap(){return `<div class="card map-card"><div class="card-head"><h3>LIVE PUBLIC MAP · HAVELI / PUNE</h3><span class="pill">OpenStreetMap · live tiles</span></div>${publicMap('publicMap',450)}</div>`}
function publicSourceCards(){return `<div class="grid two"><div class="card side-card"><div class="eyebrow">OFFICIAL LAND-RECORD SOURCES</div><h2>Government public services</h2><p class="muted">Real government service references. No private/unauthorized cadastral API access is claimed.</p><div class="source-list"><a class="source" href="https://bhumiabhilekh.maharashtra.gov.in/Services" target="_blank" rel="noopener"><b>Mahabhulekh Services</b><span>e-Nakasha / Bhu-Naksha, e-Mojani, e-Abhilekh and related services</span></a><a class="source" href="https://bhumiabhilekh.maharashtra.gov.in/Services/View712" target="_blank" rel="noopener"><b>Digital 7/12</b><span>Search by ULPIN, district, taluka, village and survey number</span></a><a class="source" href="https://www.data.gov.in/catalog/maharashtra-state-administrative-juridiction" target="_blank" rel="noopener"><b>Maharashtra State Administrative Jurisdiction</b><span>Official OGD catalogue</span></a></div></div><div class="card side-card"><div class="eyebrow">PUBLIC GEOSPATIAL DATA</div><h2>Open map + live lookup</h2><div class="field"><label>SEARCH PUBLIC PLACE</label><input id="publicSearch" placeholder="e.g. Haveli, Pune, Maharashtra"><button class="btn primary" style="margin-top:8px" onclick="searchPublicPlace()">Search live public data</button></div><div id="publicSearchResult" class="section callout">OpenStreetMap/Nominatim reference data; not legal land records.</div><div class="section"><a class="source" href="https://bhuvan-app1.nrsc.gov.in/mrd/mpr.php" target="_blank" rel="noopener"><b>ISRO Bhuvan / Panchayat Raj Map</b><span>Public geospatial viewer</span></a></div></div></div>`}
function searchPublicPlace(){const q=document.getElementById('publicSearch')?.value.trim(),out=document.getElementById('publicSearchResult');if(!q||!out)return;out.textContent='Searching OpenStreetMap public geocoding…';fetch('https://nominatim.openstreetmap.org/search?format=jsonv2&limit=5&q='+encodeURIComponent(q),{headers:{Accept:'application/json'}}).then(r=>r.json()).then(rows=>{out.innerHTML=rows.length?rows.map(x=>`<div style="margin:7px 0"><b>${esc(x.display_name)}</b><br><span class="muted">${Number(x.lat).toFixed(6)}, ${Number(x.lon).toFixed(6)}</span></div>`).join(''):'No public geocoding result found.'}).catch(()=>out.textContent='Public lookup unavailable. Check internet access and try again.')}
function pagesCommonParcel(){return state.parcels.find(x=>x.id===state.selectedParcel)||state.parcels[0]}
const pages={
command(){const p=pagesCommonParcel();document.getElementById('content').innerHTML=head('KshetraSetu Command Center','Survey → Detect → Validate → Verify → Record',`<button class="btn primary" onclick="go('field')">Open Field Mode</button><button class="btn" onclick="go('change')">Compare Parcel</button>`)+`<div class="grid kpis">${kpi('Active Projects',state.projects.length,'Local register')}${kpi('Field Points',state.fieldPoints.length,'Live/user-supplied')}${kpi('Verification Required',state.parcels.filter(x=>x.state!=='verified').length,'Officer action queue')}${kpi('Spatial Conflicts',state.parcels.filter(x=>x.state==='conflict').length,'Reference workflow')}${kpi('GCP / Control',state.controlPoints.length,'Imported evidence')}${kpi('Pending Sync',state.pending.length,'Offline queue')}${kpi('Parcel Changes',state.changeGeos.recorded&&state.changeGeos.observed?'1':'0','Source comparison')}</div><div class="grid two section">${commandMap()}<div class="card side-card"><div class="card-head" style="padding:0 0 12px;border:0"><h3>SELECTED PARCEL · ${esc(p.id)}</h3>${status(p.state)}</div><div class="metric-grid"><div class="metric"><b>${esc(p.area)} ha</b><span>Register reference</span></div><div class="metric"><b>${esc(p.newArea||'—')} ha</b><span>Resurvey reference</span></div><div class="metric"><b>${esc(p.displacement||'—')} m</b><span>Reference displacement</span></div><div class="metric"><b>${esc(p.confidence||'—')}%</b><span>Reference AI value</span></div></div><div class="section callout"><b>Spatial discrepancy requiring authorized verification.</b><br><span class="muted">Reference values are not authenticated measurements.</span></div><button class="btn primary" style="width:100%" onclick="go('twin')">Open Parcel Digital Twin</button></div></div><div class="section card side-card"><div class="card-head" style="padding:0 0 12px;border:0"><h3>ACTIVE PROJECT · ${esc(state.projects[0]?.name||'No project')}</h3><span class="status blue">${esc(state.projects[0]?.status||'NEW')}</span></div><div class="progress"><i style="width:${Math.min(100,Math.max(0,projectProgress()))}%"></i></div><div class="stat-row"><span>Project ID</span><b>${esc(state.projects[0]?.id||'—')}</b></div><div class="stat-row"><span>Location</span><span>${esc(state.projects[0]?.location||'—')}</span></div><div class="stat-row"><span>Survey area</span><b>${esc(state.projects[0]?.area||'—')}</b></div></div>`;setTimeout(()=>initMap('publicMap',18.5204,73.8567,12),0)},
twin(){const p=pagesCommonParcel(),hasB=state.boundary.length>=3,hasP=state.fieldPoints.length>0,verified=state.methodology.verification?.status==='COMPLETE';document.getElementById('content').innerHTML=head(`Parcel Digital Twin · ${p.id}`,'Traceable parcel lifecycle: record → observation → validation → verification.',`<button class="btn" onclick="go('field')">Capture Field Evidence</button><button class="btn" onclick="go('gis')">Validate Geometry</button><button class="btn" onclick="exportTwin()">Export Twin</button><button class="btn primary" onclick="verifyParcel()">${verified?'Verification Complete':'Verify Parcel'}</button>`)+`<div class="notice"><b>Data integrity:</b> reference parcel values are clearly separated from user-supplied/live evidence. No government cadastral geometry is invented.</div><div class="twin section"><div class="card twin-visual"><div class="card-head"><h3>GEOMETRY EVIDENCE VIEW</h3><span class="pill">${state.twinLayer.toUpperCase()}</span></div><div class="layer-chip">${['recorded','observed','difference','verified'].map(l=>`<button class="${state.twinLayer===l?'active':''}" onclick="state.twinLayer='${l}';pages.twin()">${l.toUpperCase()}</button>`).join('')}</div>${twinSvg(p,state.twinLayer)}</div><div class="card side-card"><div class="eyebrow">PARCEL IDENTITY</div><h2 style="margin:6px 0">P-${esc(p.id)}</h2><p class="muted">${esc(p.crop)} · ${esc(state.projects[0]?.location||'Project')}</p><div class="metric-grid"><div class="metric"><b>${esc(p.area)} ha</b><span>Register reference</span></div><div class="metric"><b>${hasP?state.fieldPoints.length:'—'}</b><span>Live observations</span></div><div class="metric"><b>${hasB?state.boundary.length:'—'}</b><span>Boundary vertices</span></div><div class="metric"><b>${verified?'VERIFIED':'PENDING'}</b><span>Officer status</span></div></div><div class="section callout"><b>Digital Parcel Evolution</b><br><span class="muted">Original Record → Digitized Parcel → Resurvey → UAV → RTK/GNSS → Candidate → Change → Field Verification → Corrected Geometry → Verified Parcel.</span></div></div></div><div class="grid two section"><div class="card side-card"><h3>LINEAGE</h3>${[['Identity',true,'Project register'],['Existing record',!!state.recordEvidence,'Uploaded record evidence'],['Field observations',hasP,'Live Field Survey'],['Boundary geometry',hasB,'Boundary editor'],['GIS validation',!!state.geometryAnalysis,'GIS Engine'],['Change analysis',!!(state.changeGeos.recorded&&state.changeGeos.observed),'Old vs New'],['Officer verification',verified,'Authorized action']].map((x,i)=>`<div class="step ${x[1]?'done':''}"><div class="stepno">${i+1}</div><div><div class="name">${x[0]}</div><div class="meta">Source: ${x[2]}</div></div>${status(x[1]?'complete':'pending')}</div>`).join('')}</div><div class="card side-card"><h3>ACTIONS</h3><div class="actions"><button class="btn" onclick="go('change')">Old vs New</button><button class="btn" onclick="go('evidence')">Audit Trail</button><button class="btn" onclick="go('method')">Methodology</button><button class="btn" onclick="sendTwinVerification()">Send to Verification</button></div></div></div>`},
projects(){const list=state.projects;document.getElementById('content').innerHTML=head('Survey Project Register','Create and manage survey projects before field-to-cadastral verification',`<button class="btn primary" onclick="openNewSurveyForm()">+ New Survey</button>`)+`<div class="card"><div class="card-head"><h3>PROJECT REGISTER</h3><span class="pill">${list.length} project${list.length===1?'':'s'}</span></div><table class="table"><thead><tr><th>Project</th><th>Location</th><th>Area</th><th>Parcels</th><th>Status</th><th>Action</th></tr></thead><tbody>${list.map(p=>`<tr><td><b>${esc(p.name)}</b><br><small class="muted">${esc(p.id)}</small></td><td>${esc(p.location)}</td><td>${esc(p.area)}</td><td>${esc(p.parcels)}</td><td>${status(p.status.includes('Complete')?'complete':'pending')}</td><td><button class="btn" onclick="openSurvey('${esc(p.id)}')">Open</button></td></tr>`).join('')}</tbody></table></div><div class="section notice"><b>Prototype data rule:</b> newly registered projects remain local prototype records until authenticated government records and authorized evidence are connected.</div>`},
method(){const stages=['Existing Record Ingestion','Cadastral Boundary Preparation','Survey Control Establishment','RTK/GNSS Control Points','UAV Flight / Orthomosaic','Ground Control Validation','Image Processing','AI Boundary Candidate Extraction','GIS Topology Validation','Change Detection','Field Verification','Final Parcel Geometry'];document.getElementById('content').innerHTML=head('Survey Methodology','Auditable 12-stage workflow from existing record to verified parcel.',`<button class="btn" onclick="completeMethodStagePrompt()">Update Stage</button><button class="btn primary" onclick="exportMethodology()">Export Method</button>`)+`<div class="notice">Every stage stores status, date, officer, source, accuracy and evidence. A stage is never marked complete merely because a screen exists.</div><div class="section card side-card">${stages.map((s,i)=>{const m=state.methodology[i]||{},done=m.status==='COMPLETE';return `<div class="step ${done?'done':''}"><div class="stepno">${i+1}</div><div><div class="name">${s}</div><div class="meta">${m.date||'Not started'} · ${m.officer||'—'} · ${m.source||'—'} · ${m.accuracy||'—'} · ${m.evidence||'No evidence linked'}</div></div>${status(done?'complete':'pending')}</div>`}).join('')}</div>`},
control(){document.getElementById('content').innerHTML=head('Survey Control Network','Real CORS/GNSS/GCP evidence inputs with provenance.',`<a class="btn primary" href="https://corswebmap.surveyofindia.gov.in/" target="_blank" rel="noopener">Open Official CORS Map</a>`)+`<div class="grid two"><div class="card side-card"><div class="eyebrow">SURVEY OF INDIA · CORS</div><h2>Authoritative reference network</h2><p class="muted">Station positions/status are read from the official service; this prototype does not fabricate station observations.</p><div class="source-list"><a class="source" href="https://corswebmap.surveyofindia.gov.in/" target="_blank"><b>Survey of India CORS Web Map</b><span>Live public reference</span></a><a class="source" href="https://onlinemaps.surveyofindia.gov.in/Digital_Product_Show.aspx/SOIFonts.aspx" target="_blank"><b>Survey of India Digital Products</b><span>CORS, GCP and geodetic resources</span></a></div><div class="section callout"><b>GNSS:</b> ${state.currentPosition?'Live position available':'No live receiver position'}</div></div><div class="card side-card"><div class="eyebrow">REAL FIELD CONTROL</div><h2>Connect GNSS receiver</h2><button class="btn primary" onclick="connectGnss()">Connect GNSS / NMEA</button><div id="gnssInfo" class="section callout">${state.currentPosition?'Receiver/device position available.':'No receiver connected. No RTK accuracy is fabricated.'}</div></div></div><div class="section card"><div class="card-head"><h3>GROUND CONTROL EVIDENCE</h3><span class="pill">${state.controlPoints.length} imported</span></div><div class="field"><label>IMPORT REAL GCP / CONTROL CSV</label><input id="gcpFile" type="file" accept=".csv,.txt" onchange="importGcpCsv(event)"></div><div id="gcpTable" class="section">${gcpTable()}</div></div>`},
field(){document.getElementById('content').innerHTML=head('Live Field Survey Mode','Real device/GNSS input, boundary editor, evidence capture and offline queue.',`<button class="btn ${state.offline?'warn':'primary'}" onclick="toggleOffline()">${state.offline?'Go Online':'Enable Offline Mode'}</button><button class="btn" onclick="boundaryCapture()">Close Boundary</button>`)+`<div class="grid two"><div class="card side-card"><div class="eyebrow">LIVE POSITION SOURCE</div><h2 id="fieldSource">${state.currentPosition?'Live device/GNSS position':'Waiting for device location'}</h2><div class="metric-grid"><div class="metric"><b id="fieldLat">${state.currentPosition?state.currentPosition.lat.toFixed(7):'—'}</b><span>Latitude</span></div><div class="metric"><b id="fieldLon">${state.currentPosition?state.currentPosition.lon.toFixed(7):'—'}</b><span>Longitude</span></div><div class="metric"><b id="fieldAcc">${state.currentPosition?.accuracy?state.currentPosition.accuracy.toFixed(2)+' m':'—'}</b><span>Accuracy</span></div><div class="metric"><b id="fieldAlt">${state.currentPosition?.altitude??'—'}</b><span>Altitude</span></div></div><div class="section field-actions"><button class="btn primary wide" onclick="startRealLocation()">START LIVE LOCATION</button><button class="btn" onclick="connectGnss()">CONNECT GNSS</button><button class="btn" onclick="captureRealPoint()">CAPTURE POINT</button><label class="btn" style="display:block;text-align:center"><input type="file" accept="image/*" capture="environment" style="display:none" onchange="capturePhoto(event)">CAPTURE PHOTO</label><button class="btn" onclick="addNote()">ADD FIELD NOTE</button><button class="btn" onclick="undoBoundary()">UNDO</button><button class="btn" onclick="redoBoundary()">REDO</button><button class="btn" onclick="editBoundary()">EDIT BOUNDARY</button><button class="btn danger wide" onclick="finishParcel()">SUBMIT FOR VERIFICATION</button></div><div id="fieldNotice" class="section callout">Browser GPS is real device data but is not automatically RTK. RTK status is shown only from a receiver.</div></div><div class="card map-card"><div class="card-head"><h3>FIELD LOCATION</h3><span class="pill">OpenStreetMap</span></div>${publicMap('fieldMap',520)}</div></div><div class="section card"><div class="card-head"><h3>CAPTURED OBSERVATIONS</h3><span class="pill">${state.fieldPoints.length} points · ${state.pending.length} pending</span></div>${state.fieldPoints.length?state.fieldPoints.map((p,i)=>`<div class="stat-row"><span>Observation ${i+1}</span><span>${esc(p.lat)}, ${esc(p.lon)} · ${esc(p.acc||'—')} · ${esc(p.source||'device')} · ${esc(p.time)}</span></div>`).join(''):'<div class="empty">No observations captured yet.</div>'}<div class="section"><b>Boundary:</b> ${state.boundary.length?state.boundary.length+' vertices':'Not closed'} · <b>Notes:</b> ${state.notes.length} · <b>Photos:</b> ${state.photos.length} · <b>Pending sync:</b> ${state.pending.length}</div></div>`;setTimeout(()=>{window.ksFieldMap=initMap('fieldMap',state.currentPosition?.lat||18.5204,state.currentPosition?.lon||73.8567,15);if(state.currentPosition)showFieldMarker()},0)},
uav(){document.getElementById('content').innerHTML=head('UAV Survey Workspace','Import real imagery/orthomosaic/GeoJSON and track every processing prerequisite.',`<a class="btn" href="https://bhuvan.nrsc.gov.in/home/" target="_blank">Open ISRO Bhuvan</a>`)+`<div class="grid two"><div class="card side-card"><div class="eyebrow">REAL SURVEY INPUT</div><h2>Import UAV evidence</h2><div class="field"><label>ORTHOMOSAIC / IMAGE</label><input type="file" accept="image/*,.tif,.tiff,.jp2" onchange="loadUavFile(event)"></div><div class="field"><label>BOUNDARY / FLIGHT GEOJSON</label><input type="file" accept=".geojson,.json" onchange="loadGeoJson(event)"></div><div class="field"><label>FLIGHT METADATA JSON</label><input type="file" accept=".json" onchange="loadFlightMetadata(event)"></div><div id="uavFileInfo" class="section callout">${state.uavFile?esc(state.uavFile.name):'No UAV file loaded.'}</div></div><div class="card side-card"><div class="eyebrow">DATA INTEGRITY</div><h2>UAV provenance</h2><div class="stat-row"><span>Image/file</span><b>${state.uavFile?'LOADED':'MISSING'}</b></div><div class="stat-row"><span>GeoJSON</span><b>${state.loadedGeoJson?'LOADED':'MISSING'}</b></div><div class="stat-row"><span>Flight metadata</span><b>${state.uavMetadata?'LOADED':'MISSING'}</b></div><div class="section callout">Photogrammetric orthomosaic generation requires a real processing engine/output. The prototype will not claim it happened without output evidence.</div></div></div><div class="section card"><div class="card-head"><h3>PROCESSING PIPELINE</h3><button class="btn primary" onclick="runPipeline()">Run Validation</button></div>${['Image Validation','Georeferencing','Orthomosaic Generation','Quality Check','Feature Extraction','Boundary Analysis'].map((x,i)=>`<div class="pipe"><span>${i+1}. ${x}</span><span class="status amber" id="uavStage${i}">${uavStage(i)}</span></div>`).join('')}<div class="section callout">Input validation is executable locally. Actual photogrammetry is complete only when a real orthomosaic/processing output is supplied.</div></div>`},
ai(){document.getElementById('content').innerHTML=head('AI-Assisted Boundary Analysis','Deterministic candidate extraction from supplied geometry/field points, with transparent scoring; no legal decisions.',`<button class="btn" onclick="go('uav')">Load Survey Input</button><button class="btn primary" onclick="runCandidateExtraction()">Generate Candidate</button>`)+`<div class="grid two"><div class="card side-card"><div class="eyebrow">INPUT</div><div id="aiGeometryInfo" class="section callout">${state.loadedGeoJson?'GeoJSON loaded':'No geometry loaded. You can use captured field points.'}</div><div class="section"><b>Candidate source:</b> ${state.fieldPoints.length>=3?'field observations':'imported GeoJSON required'}</div></div><div class="card side-card"><div class="eyebrow">CANDIDATE RESULT</div><div id="aiResult" class="section callout">No candidate generated.</div><div class="section callout warning"><b>AI-assisted boundary candidate only.</b> Authorized personnel remain responsible for final verification.</div><div class="section callout danger-box"><b>Cannot:</b> decide ownership · resolve disputes · declare legal encroachment · modify official records.</div></div></div>`},
gis(){document.getElementById('content').innerHTML=head('GIS Validation Engine','Executable geometry/topology checks on supplied GeoJSON or captured boundary.',`<button class="btn" onclick="go('uav')">Import Geometry</button><button class="btn primary" onclick="runGISValidation()">Validate Geometry</button><button class="btn" onclick="autoFixDraft()">Auto-Fix Draft</button>`)+`<div class="grid two"><div class="card side-card"><div class="eyebrow">VALIDATION INPUT</div><div id="gisInfo" class="section callout">${state.loadedGeoJson?'Loaded GeoJSON':'Use UAV → import GeoJSON or Field Survey → close boundary.'}</div><div class="section"><b>Boundary vertices:</b> ${state.boundary.length}</div></div><div class="card side-card"><h3>TOPOLOGY STATUS</h3><div id="gisResults">${state.geometryAnalysis?renderAnalysis(state.geometryAnalysis):'<div class="empty">Run validation to calculate closure, self-intersection, area, duplicate and geometry checks.</div>'}</div></div></div><div class="section card side-card"><h3>OFFICER CONFIRMATION</h3><div class="notice">Auto-fix is only a draft. It never silently changes source evidence.</div><div class="actions section"><button class="btn primary" onclick="confirmAutoFix()">Confirm Draft Fix</button><button class="btn" onclick="revertDraftFix()">Revert Draft</button></div></div>`},
change(){document.getElementById('content').innerHTML=head('Cadastral Change Analysis','OLD vs NEW comparison using source geometries, paper-record evidence and coordinate-level displacement.',`<button class="btn" onclick="go('public')">Public Sources</button>`)+`<div class="grid two"><div class="card side-card"><div class="eyebrow">RECORDED / OLD</div><div class="field"><label>RECORDED GEOJSON</label><input id="recordedFile" type="file" accept=".geojson,.json" onchange="loadChangeFile(event,'recorded')"></div><div id="recordedInfo" class="section callout">${state.changeGeos.recorded?'Recorded geometry loaded.':'No recorded geometry loaded.'}</div><div class="field"><label>OLD PAPER / RECORD EVIDENCE</label><input type="file" accept="image/*,.pdf" onchange="loadRecordEvidence(event)"></div><div class="section callout">${state.recordEvidence?`Evidence: ${esc(state.recordEvidence.name)} · SHA-256 ${esc(state.recordEvidence.hash)}`:'Upload a scan/photo/PDF. The original file is hashed for integrity.'}</div></div><div class="card side-card"><div class="eyebrow">OBSERVED / NEW</div><div class="field"><label>OBSERVED GEOJSON</label><input id="observedFile" type="file" accept=".geojson,.json" onchange="loadChangeFile(event,'observed')"></div><div id="observedInfo" class="section callout">${state.changeGeos.observed?'Observed geometry loaded.':'No observed geometry loaded.'}</div><button class="btn primary" onclick="compareLoadedGeometries()">Compare Old vs New</button></div></div><div class="section card side-card"><div class="card-head"><h3>PAPER RECORD → GEOREFERENCE</h3><span class="pill">${state.paperGeoref?'READY':'3+ CONTROL PAIRS REQUIRED'}</span></div><p class="muted">For a scanned paper map, enter pixel coordinates from the scan and the corresponding known longitude/latitude control coordinates. The prototype computes a transparent affine transform; it does not invent control coordinates.</p><div class="notice">Use at least 3 non-collinear control pairs. For a real survey, the known coordinates should come from authorized GCP/RTK/control evidence.</div><div class="section"><table class="table"><thead><tr><th>#</th><th>Paper X</th><th>Paper Y</th><th>Known Lon</th><th>Known Lat</th><th></th></tr></thead><tbody>${[0,1,2].map(i=>{const p=state.paperGcpPairs[i]||{};return `<tr><td>${i+1}</td><td><input id="pgx${i}" type="number" step="0.01" value="${p.x??''}"></td><td><input id="pgy${i}" type="number" step="0.01" value="${p.y??''}"></td><td><input id="pglon${i}" type="number" step="0.0000001" value="${p.lon??''}"></td><td><input id="pgllat${i}" type="number" step="0.0000001" value="${p.lat??''}"></td><td>GCP ${i+1}</td></tr>`}).join('')}</tbody></table></div><div class="actions"><button class="btn primary" onclick="computePaperGeoreference()">Compute Georeference</button><button class="btn" onclick="clearPaperGeoreference()">Clear</button></div><div class="section callout">${state.paperGeoref?`Affine transform ready. RMS residual: ${state.paperGeoref.rms.toFixed(6)} coordinate units. Source control pairs: ${state.paperGcpPairs.length}.`:'No georeference transform computed yet.'}</div></div><div class="section card"><div class="card-head"><h3>CHANGE RESULT</h3><span class="pill">Source evidence required</span></div><div id="changeResult" class="callout">${state.changeGeos.recorded&&state.changeGeos.observed?changeResultHtml():'Load both geometries to calculate area difference and maximum nearest-vertex displacement.'}</div></div><div class="section notice"><b>Important:</b> Paper upload + hash + georeferencing workflow is implemented, but the system will not claim a paper map is legally authoritative or georeferenced until real control coordinates are supplied.</div>`},
evidence(){document.getElementById('content').innerHTML=head('Evidence & Audit Trail','Source-bound evidence register, hashes, field observations and officer actions.',`<button class="btn primary" onclick="exportData()">Export Survey Record</button>`)+`<div class="grid two"><div class="card side-card"><h3>REAL EVIDENCE REGISTER</h3>${[['Field observations',state.fieldPoints.length],['Boundary vertices',state.boundary.length],['GCP/control points',state.controlPoints.length],['Field photos',state.photos.length],['Field notes',state.notes.length],['Pending offline records',state.pending.length],['Old record evidence',state.recordEvidence?'1':'0']].map(x=>`<div class="stat-row"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}<div class="section callout">Evidence means user-supplied files, public references, device observations and officer actions. Prototype reference KPIs are not authenticated measurements.</div></div><div class="card side-card"><h3>AUDIT TIMELINE</h3>${state.audit.length?`<div class="timeline">${state.audit.slice().reverse().map((x,i)=>`<div class="step done"><div class="stepno">${i+1}</div><div><div class="name">${esc(x.action)}</div><div class="meta">${esc(x.time)} · ${esc(x.officer)}</div></div><span class="status green">LOGGED</span></div>`).join('')}</div>`:'<div class="callout">No officer actions logged yet.</div>'}</div></div><div class="section card side-card"><h3>FIELD NOTES & PHOTOS</h3>${state.notes.map(n=>`<div class="stat-row"><span>${esc(n.time)}</span><span>${esc(n.text)}</span></div>`).join('')||'No notes captured.'}</div>`},
public(){document.getElementById('content').innerHTML=head('Public Data & Sources','Real public geospatial data and official land-record service references.',`<button class="btn" onclick="go('command')">Back to Command Center</button>`)+`<div class="section card map-card"><div class="card-head"><h3>LIVE OPENSTREETMAP DATA</h3><span class="pill">Public basemap</span></div>${publicMap('publicMap',420)}</div>${publicSourceCards()}<div class="section card side-card"><div class="card-head" style="padding:0 0 12px;border:0"><h3>DATA PROVENANCE</h3>${status('complete')}</div><div class="stat-row"><span>Basemap</span><b>OpenStreetMap</b></div><div class="stat-row"><span>Geocoding</span><b>Nominatim / OpenStreetMap</b></div><div class="stat-row"><span>Land-record service</span><b>Maharashtra Bhumi Abhilekh</b></div><div class="stat-row"><span>Cadastral parcel layer</span><b>Not embedded without authorized source</b></div></div>`;setTimeout(()=>initMap('publicMap',18.5204,73.8567,12),0)}
};
function projectProgress(){let n=Object.values(state.methodology).filter(x=>x?.status==='COMPLETE').length;return Math.round(n/12*100)}
function gcpTable(){return state.controlPoints.length?`<table class="table"><thead><tr><th>Point</th><th>Latitude</th><th>Longitude</th><th>Accuracy</th></tr></thead><tbody>${state.controlPoints.map(p=>`<tr><td>${esc(p.id)}</td><td>${esc(p.lat)}</td><td>${esc(p.lon)}</td><td>${esc(p.acc||'—')}</td></tr>`).join('')}</tbody></table>`:'<div class="callout">Upload the surveyor actual control-point CSV.</div>'}
function twinSvg(p,layer){const pts=state.boundary.map(x=>[Number(x.lon),Number(x.lat)]).filter(x=>Number.isFinite(x[0])&&Number.isFinite(x[1]));if(pts.length<3)return `<div style="height:100%;min-height:420px;display:grid;place-items:center;padding:40px;text-align:center"><div><div class="eyebrow">NO FABRICATED GEOMETRY</div><h2>${layer.toUpperCase()} unavailable</h2><p class="muted">Capture a real field boundary or import authorized geometry before drawing this layer.</p><button class="btn primary" onclick="go('field')">Open Field Survey</button></div></div>`;const minX=Math.min(...pts.map(x=>x[0])),maxX=Math.max(...pts.map(x=>x[0])),minY=Math.min(...pts.map(x=>x[1])),maxY=Math.max(...pts.map(x=>x[1]));const sx=v=>80+((v-minX)/(maxX-minX||1))*600,sy=v=>390-((v-minY)/(maxY-minY||1))*280,path=pts.map((x,i)=>(i?'L':'M')+sx(x[0]).toFixed(1)+' '+sy(x[1]).toFixed(1)).join(' ')+' Z';return `<svg viewBox="0 0 760 480"><rect width="760" height="480" fill="#09252d"/><path d="${path}" fill="#49d29a20" stroke="#66dfb0" stroke-width="5"/>${pts.map((x,i)=>`<circle cx="${sx(x[0])}" cy="${sy(x[1])}" r="5" fill="#fff"/><text x="${sx(x[0])+8}" y="${sy(x[1])-8}" fill="#c9dde1" font-size="10">${i+1}</text>`).join('')}<text x="22" y="32" fill="#d4e7e6" font-size="12">P-${esc(p.id)} · ${esc(layer.toUpperCase())}</text><text x="22" y="452" fill="#8fa9b1" font-size="11">Source: captured/user-supplied geometry; not government authenticated.</text></svg>`}
function openNewSurveyForm(){document.getElementById('surveyModal')?.remove();const m=document.createElement('div');m.id='surveyModal';m.className='modal-backdrop';m.innerHTML=`<div class="modal-card"><div class="card-head"><div><div class="eyebrow">SURVEY PROJECT REGISTER</div><h2 id="newSurveyTitle">Create New Survey Project</h2></div><button class="btn ghost" onclick="closeNewSurveyForm()">✕</button></div><div class="grid two"><div class="field"><label>PROJECT NAME *</label><input id="newSurveyName" maxlength="120"></div><div class="field"><label>PROJECT ID *</label><input id="newSurveyId" maxlength="50"></div><div class="field"><label>STATE *</label><input id="newSurveyState" value="Maharashtra"></div><div class="field"><label>DISTRICT *</label><input id="newSurveyDistrict"></div><div class="field"><label>TALUKA / TEHSIL</label><input id="newSurveyTaluka"></div><div class="field"><label>VILLAGE</label><input id="newSurveyVillage"></div><div class="field"><label>SURVEY AREA (HA)</label><input id="newSurveyArea" type="number" min="0" step="0.01"></div><div class="field"><label>PARCEL COUNT</label><input id="newSurveyParcels" type="number" min="0" step="1"></div></div><div class="notice">New project is local prototype data until authorized records/evidence are attached.</div><div class="actions" style="justify-content:flex-end;margin-top:16px"><button class="btn" onclick="closeNewSurveyForm()">Cancel</button><button class="btn primary" onclick="createSurveyProject()">Create Survey</button></div></div>`;document.body.appendChild(m);m.onclick=e=>{if(e.target===m)closeNewSurveyForm()};document.getElementById('newSurveyName').focus()}
function closeNewSurveyForm(){document.getElementById('surveyModal')?.remove()}
function createSurveyProject(){const v=id=>document.getElementById(id)?.value.trim()||'',name=v('newSurveyName'),id=v('newSurveyId'),st=v('newSurveyState'),district=v('newSurveyDistrict'),taluka=v('newSurveyTaluka'),village=v('newSurveyVillage'),area=v('newSurveyArea'),parcels=v('newSurveyParcels');if(!name||!id||!st||!district)return toast('Fill Project Name, Project ID, State and District.');if(state.projects.some(p=>String(p.id).toLowerCase()===id.toLowerCase()))return toast('Project ID already exists.');if(Number(area)<0||Number(parcels)<0)return toast('Area/parcel count cannot be negative.');state.projects.unshift({id,name,location:[village,taluka,district,st].filter(Boolean).join(' · '),area:area?Number(area).toFixed(2)+' ha':'Not specified',parcels:parcels||'0',status:'New / Not Started'});audit('Survey project created: '+id,{projectId:id});closeNewSurveyForm();persist();pages.projects();toast('Survey project created successfully.')}
function openSurvey(id){const p=state.projects.find(x=>x.id===id);if(p){state.activeProjectId=id;audit('Opened survey project: '+id,{projectId:id});go('method')}}
function completeMethodStagePrompt(){const i=prompt('Stage number (1-12) to mark COMPLETE:');const n=Number(i);if(!Number.isInteger(n)||n<1||n>12)return toast('Enter a stage number from 1 to 12.');const source=prompt('Evidence/source description (required):');if(!source)return toast('Evidence/source is required.');const acc=prompt('Accuracy (optional):')||'—';state.methodology[n-1]={status:'COMPLETE',date:new Date().toISOString(),officer:'SURVEY-001',source,evidence:source,accuracy:acc};audit('Methodology stage completed: '+n,{stage:n});persist();pages.method()}
function exportMethodology(){const blob=new Blob([JSON.stringify({project:state.activeProjectId||state.projects[0]?.id,methodology:state.methodology,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});downloadBlob(blob,'kshetrasetu-methodology.json');audit('Methodology exported')}
function startRealLocation(){if(!navigator.geolocation)return toast('Browser geolocation unavailable.');if(state.geoWatch)navigator.geolocation.clearWatch(state.geoWatch);state.geoWatch=navigator.geolocation.watchPosition(pos=>{const c=pos.coords;state.currentPosition={lat:c.latitude,lon:c.longitude,accuracy:c.accuracy,altitude:c.altitude};updateFieldUI();showFieldMarker()},err=>toast('Location error: '+err.message),{enableHighAccuracy:true,maximumAge:1000,timeout:10000});audit('Live device location started');toast('Live device location started.')}
function updateFieldUI(){const c=state.currentPosition;if(!c)return;const set=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v};set('fieldLat',c.lat.toFixed(7));set('fieldLon',c.lon.toFixed(7));set('fieldAcc',c.accuracy?c.accuracy.toFixed(2)+' m':'—');set('fieldAlt',c.altitude==null?'—':c.altitude.toFixed(1)+' m');set('fieldSource','Browser GNSS/GPS position');const n=document.getElementById('fieldNotice');if(n)n.innerHTML='<b>Live device position.</b> Browser accuracy is reported by the device; it is not an RTK/NRTK claim.'}
function showFieldMarker(){if(!window.ksFieldMap||!state.currentPosition||typeof L==='undefined')return;const c=state.currentPosition;window.ksFieldMap.setView([c.lat,c.lon],17);if(window.ksFieldMarker)window.ksFieldMarker.setLatLng([c.lat,c.lon]);else window.ksFieldMarker=L.marker([c.lat,c.lon]).addTo(window.ksFieldMap).bindPopup('Live device position').openPopup()}
function captureRealPoint(){if(!state.currentPosition)return toast('Start live location or connect GNSS first.');state.fieldPoints.push({lat:state.currentPosition.lat,lon:state.currentPosition.lon,accuracy:state.currentPosition.accuracy,acc:state.currentPosition.accuracy?state.currentPosition.accuracy.toFixed(2)+' m':'—',source:state.gnssPort?'Connected GNSS/NMEA':'Browser GNSS/GPS',time:new Date().toISOString()});state.pending.push({type:'FIELD_OBSERVATION',point:state.fieldPoints.at(-1)});state.boundaryFuture=[];audit('Field point captured');persist();pages.field();toast('Field point captured.')}
async function connectGnss(){if(!('serial' in navigator))return toast('Web Serial unavailable. Use Chrome/Edge or browser GPS.');try{const port=await navigator.serial.requestPort();await port.open({baudRate:4800});state.gnssPort=port;const info=document.getElementById('gnssInfo');if(info)info.innerHTML='<b>GNSS serial connected.</b> Reading NMEA GGA…';const decoder=new TextDecoderStream();port.readable.pipeTo(decoder.writable);const reader=decoder.readable.getReader();let buf='';while(true){const {value,done}=await reader.read();if(done)break;buf+=value;const lines=buf.split(/\r?\n/);buf=lines.pop()||'';for(const line of lines)if(line.startsWith('$GNGGA')||line.startsWith('$GPGGA'))parseGga(line)}}catch(e){toast('GNSS connection not opened: '+e.message)}}
function parseGga(line){const a=line.split(','),lat=nmeaCoord(a[2],a[3]),lon=nmeaCoord(a[4],a[5]);if(lat==null||lon==null)return;const fix=Number(a[6]||0),sats=a[7]||'—',alt=a[9]||'—';state.currentPosition={lat,lon,accuracy:null,altitude:Number(alt),fix,sats};const n=document.getElementById('fieldNotice');if(n)n.innerHTML=`<b>Live NMEA receiver.</b> Fix=${fix}, satellites=${esc(sats)}. RTK status is reported only from receiver NMEA.`;updateFieldUI()}
function nmeaCoord(v,hemi){if(!v)return null;const d=parseFloat(v);if(!Number.isFinite(d))return null;const deg=Math.floor(d/100),min=d-deg*100;let out=deg+min/60;if(hemi==='S'||hemi==='W')out=-out;return out}
async function importGcpCsv(event){const f=event.target.files?.[0];if(!f)return;const text=await f.text(),rows=text.trim().split(/\r?\n/).map(x=>x.split(','));if(!rows.length)return;const h=rows.shift().map(x=>x.trim().toLowerCase());const idx=(re)=>h.findIndex(x=>re.test(x));state.controlPoints=rows.filter(r=>r.length).map(r=>({id:r[idx(/id|point/)]||'—',lat:r[idx(/lat/)]||'—',lon:r[idx(/lon|lng/)]||'—',acc:r[idx(/acc|error/)]||'—',source:f.name}));state.pending.push({type:'GCP_IMPORT',count:state.controlPoints.length,time:new Date().toISOString()});audit('Real GCP/control CSV imported',{count:state.controlPoints.length});persist();pages.control();toast(`${state.controlPoints.length} control points imported.`)}
async function loadUavFile(event){const f=event.target.files?.[0];if(!f)return;state.uavFile={name:f.name,size:f.size,type:f.type};audit('UAV evidence file loaded: '+f.name);const e=document.getElementById('uavFileInfo');if(e)e.innerHTML=`<b>Loaded:</b> ${esc(f.name)}<br>${f.size.toLocaleString()} bytes · ${esc(f.type||'unknown')}<br><span class="muted">User-supplied evidence; provenance preserved locally.</span>`;toast('UAV file loaded.')}
async function loadGeoJson(event){const f=event.target.files?.[0];if(!f)return;try{const geo=JSON.parse(await f.text());if(!geometryFromGeoJSON(geo))throw Error('No Polygon/MultiPolygon geometry found.');state.loadedGeoJson=geo;state.pending.push({type:'GEOJSON_IMPORT',file:f.name,time:new Date().toISOString()});audit('GeoJSON geometry imported: '+f.name);persist();pages.uav();toast('GeoJSON loaded.')}catch(e){toast('Invalid GeoJSON: '+e.message)}}
async function loadFlightMetadata(event){const f=event.target.files?.[0];if(!f)return;try{state.uavMetadata=JSON.parse(await f.text());audit('UAV flight metadata imported: '+f.name);persist();pages.uav();toast('Flight metadata loaded.')}catch(e){toast('Invalid metadata JSON.')}}
function geometryFromGeoJSON(g){if(!g)return null;if(g.type==='Feature')return g.geometry;if(g.type==='FeatureCollection')return g.features.find(f=>f.geometry&&['Polygon','MultiPolygon'].includes(f.geometry.type))?.geometry;return ['Polygon','MultiPolygon'].includes(g.type)?g:null}
function ringsFromGeometry(g){if(!g)return[];if(g.type==='Polygon')return g.coordinates||[];if(g.type==='MultiPolygon')return (g.coordinates||[]).flat();return[]}
function polygonAreaM2(coords){if(!coords||coords.length<3)return 0;const lat0=coords.reduce((a,p)=>a+p[1],0)/coords.length,kx=111320*Math.cos(lat0*Math.PI/180),ky=110540;let area=0;for(let i=0,j=coords.length-1;i<coords.length;j=i++)area+=(coords[j][0]*kx)*(coords[i][1]*ky)-(coords[i][0]*kx)*(coords[j][1]*ky);return Math.abs(area/2)}
function segmentCross(a,b,c,d){const cross=(p,q,r)=>(q[0]-p[0])*(r[1]-p[1])-(q[1]-p[1])*(r[0]-p[0]);const o1=cross(a,b,c),o2=cross(a,b,d),o3=cross(c,d,a),o4=cross(c,d,b);return ((o1>0&&o2<0)||(o1<0&&o2>0))&&((o3>0&&o4<0)||(o3<0&&o4>0))}
function hasSelfIntersection(ring){if(!ring||ring.length<4)return false;const pts=ring[0][0]===ring.at(-1)[0]&&ring[0][1]===ring.at(-1)[1]?ring.slice(0,-1):ring;for(let i=0;i<pts.length;i++){for(let j=i+1;j<pts.length;j++){if(j===i||j===i+1||(i===0&&j===pts.length-1))continue;if(segmentCross(pts[i],pts[(i+1)%pts.length],pts[j],pts[(j+1)%pts.length]))return true}}return false}
function bbox(r){const xs=r.map(p=>p[0]),ys=r.map(p=>p[1]);return [Math.min(...xs),Math.min(...ys),Math.max(...xs),Math.max(...ys)]}
function bboxOverlap(a,b){return !(a[2]<b[0]||b[2]<a[0]||a[3]<b[1]||b[3]<a[1])}
function realGeometrySummary(geo){const g=geometryFromGeoJSON(geo);if(!g)return null;const rings=ringsFromGeometry(g),outer=rings[0]||[],closed=outer.length>2&&outer[0][0]===outer.at(-1)[0]&&outer[0][1]===outer.at(-1)[1];return {type:g.type,vertices:outer.length,closed,selfIntersection:hasSelfIntersection(outer),areaHa:(polygonAreaM2(outer)/10000).toFixed(4),bbox:bbox(outer),rings}};
function currentGeometry(){if(state.loadedGeoJson)return geometryFromGeoJSON(state.loadedGeoJson);if(state.boundary.length>=3)return {type:'Polygon',coordinates:[[...state.boundary.map(p=>[Number(p.lon),Number(p.lat)]),[Number(state.boundary[0].lon),Number(state.boundary[0].lat)]]]};return null}
function collectionTopology(geo){
 const features=geo?.type==='FeatureCollection'?(geo.features||[]):[{geometry:geometryFromGeoJSON(geo)}];const polys=features.map(f=>geometryFromGeoJSON(f.geometry||f)).filter(Boolean);let overlaps=0,slivers=0,duplicate=0;
 const summaries=polys.map(g=>realGeometrySummary(g));for(let i=0;i<summaries.length;i++){if(Number(summaries[i].areaHa)>0&&Number(summaries[i].areaHa)<0.0005)slivers++;for(let j=i+1;j<summaries.length;j++){if(JSON.stringify(summaries[i].bbox)===JSON.stringify(summaries[j].bbox)&&Math.abs(Number(summaries[i].areaHa)-Number(summaries[j].areaHa))<0.000001)duplicate++;if(bboxOverlap(summaries[i].bbox,summaries[j].bbox)){const a=summaries[i].rings[0]||[],b=summaries[j].rings[0]||[];let cross=false;for(let x=0;x<a.length-1&&!cross;x++)for(let y=0;y<b.length-1;y++)if(segmentCross(a[x],a[x+1],b[y],b[y+1])){cross=true;break}const inside=(r,p)=>{let hit=false;for(let k=0,l=r.length-1;k<r.length;l=k++){const xi=r[k][0],yi=r[k][1],xj=r[l][0],yj=r[l][1],inter=((yi>p[1])!==(yj>p[1]))&&(p[0]<(xj-xi)*(p[1]-yi)/(yj-yi)+xi);if(inter)hit=!hit}return hit};if(cross||inside(a,b[0])||inside(b,a[0]))overlaps++}}}
 return {overlaps,slivers,duplicate,featureCount:polys.length};
}
function validateGeometry(geo){const g=geometryFromGeoJSON(geo);if(!g)return null;const rings=ringsFromGeometry(g),outer=rings[0]||[],closed=outer.length>2&&outer[0][0]===outer.at(-1)[0]&&outer[0][1]===outer.at(-1)[1],selfIntersection=hasSelfIntersection(outer),areaHa=(polygonAreaM2(outer)/10000).toFixed(4);const issues=[];if(!closed)issues.push('Boundary not closed');if(selfIntersection)issues.push('Self-intersection detected');if(outer.length<4)issues.push('Too few vertices');if(Number(areaHa)===0)issues.push('Zero area');const duplicateVertices=outer.slice(0,-1).filter((p,i,a)=>a.some((q,j)=>j!==i&&p[0]===q[0]&&p[1]===q[1])).length;const col=collectionTopology(geo);if(col.overlaps)issues.push(`${col.overlaps} polygon overlap(s)`);if(col.duplicate)issues.push(`${col.duplicate} duplicate polygon(s)`);if(col.slivers)issues.push(`${col.slivers} sliver polygon(s)`);return {type:g.type,vertices:outer.length,closed,selfIntersection,areaHa,bbox:bbox(outer),rings,duplicateVertices,valid:issues.length===0,issues,overlapCount:col.overlaps,gapCount:'NOT_INFERRED',sliverCount:col.slivers,duplicatePolygons:col.duplicate,featureCount:col.featureCount,continuity:col.featureCount>1?'CHECKED':'SINGLE GEOMETRY'} }
function renderAnalysis(a){return [['Polygon validity',a.valid?'PASS':'FAIL',a.valid?'green':'red'],['Boundary closure',a.closed?'PASS':'FAIL',a.closed?'green':'red'],['Self-intersection',a.selfIntersection?'FAIL':'PASS',a.selfIntersection?'red':'green'],['Duplicate vertices',String(a.duplicateVertices),a.duplicateVertices?'red':'green'],['Area',a.areaHa+' ha','blue'],['Overlaps',String(a.overlapCount),a.overlapCount?'red':'green'],['Gaps',String(a.gapCount),a.gapCount?'amber':'green'],['Slivers',String(a.sliverCount),'blue'],['Continuity',a.continuity,'green']].map(x=>`<div class="stat-row"><span>${x[0]}</span><span class="status ${x[2]}">${x[1]}</span></div>`).join('')+`<div class="section callout">${a.issues.length?'Issues: '+a.issues.map(esc).join('; '):'No detected issues in supplied geometry.'}</div>`}
function runGISValidation(){const g=currentGeometry();if(!g)return toast('Load GeoJSON or close a field boundary first.');state.geometryAnalysis=validateGeometry(g);audit('GIS topology validation completed',{valid:state.geometryAnalysis.valid});persist();pages.gis();toast(state.geometryAnalysis.valid?'Geometry validation PASS.':'Geometry validation found issues.')}
function autoFixDraft(){const g=currentGeometry();if(!g)return toast('No geometry to fix.');const rings=ringsFromGeometry(g);const r=rings[0];if(!r.length)return toast('No polygon ring.');const fixed=[...r];if(fixed.length>2&&(fixed[0][0]!==fixed.at(-1)[0]||fixed[0][1]!==fixed.at(-1)[1]))fixed.push([...fixed[0]]);state.draftFix={type:'Polygon',coordinates:[fixed]};audit('GIS auto-fix draft generated');toast('Draft fix generated. Officer confirmation required.');pages.gis()}
function confirmAutoFix(){if(!state.draftFix)return toast('Generate an auto-fix draft first.');state.loadedGeoJson=state.draftFix;state.geometryAnalysis=validateGeometry(state.draftFix);state.draftFix=null;audit('Officer confirmed GIS draft fix');persist();pages.gis();toast('Draft fix confirmed.')}
function revertDraftFix(){state.draftFix=null;toast('Draft fix reverted.')}
function runCandidateExtraction(){let geo=currentGeometry();if(!geo&&state.fieldPoints.length>=3)geo={type:'Polygon',coordinates:[[...convexHull(state.fieldPoints.map(p=>[Number(p.lon),Number(p.lat)])),...[]]]};if(!geo)return toast('Provide a GeoJSON polygon or at least 3 field points.');const a=validateGeometry(geo);const score=Math.max(50,Math.min(99,Math.round((a.closed?35:10)+(a.selfIntersection?0:25)+(a.areaHa>0?20:0)+(state.controlPoints.length?10:0)+(state.fieldPoints.length>=3?10:0))));const uncertainty=a.selfIntersection?2:a.issues.length?1:0;document.getElementById('aiResult').innerHTML=`<b>Candidate boundary generated from supplied spatial evidence.</b><br>Transparent prototype score: <b>${score}%</b><br>Uncertain segments: ${uncertainty}<br>Geometry: ${a.valid?'valid':'requires correction'}<br><span class="muted">This is a deterministic prototype candidate score, not a trained-model confidence or legal finding.</span><div class="section actions"><button class="btn" onclick="acceptCandidate()">Accept Candidate</button><button class="btn" onclick="go('gis')">Edit / Validate</button><button class="btn" onclick="runCandidateExtraction()">Rerun</button><button class="btn primary" onclick="sendTwinVerification()">Send to Field Verification</button></div>`;state.aiCandidate=geo;audit('AI-assisted prototype candidate generated',{score});persist()}
function convexHull(points){const p=[...points].sort((a,b)=>a[0]-b[0]||a[1]-b[1]);if(p.length<=1)return p;const cross=(o,a,b)=>(a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0]);const lo=[];for(const x of p){while(lo.length>=2&&cross(lo.at(-2),lo.at(-1),x)<=0)lo.pop();lo.push(x)}const hi=[];for(let i=p.length-1;i>=0;i--){const x=p[i];while(hi.length>=2&&cross(hi.at(-2),hi.at(-1),x)<=0)hi.pop();hi.push(x)}return lo.slice(0,-1).concat(hi.slice(0,-1)).concat([lo[0]])}
function acceptCandidate(){if(!state.aiCandidate)return toast('Generate a candidate first.');const g=geometryFromGeoJSON(state.aiCandidate);state.boundary=(g.coordinates[0]||[]).slice(0,-1).map(p=>({lat:p[1],lon:p[0],source:'Candidate geometry'}));audit('Candidate boundary accepted as draft for officer review');persist();go('gis')}
function geometryFromBoundary(){if(state.boundary.length<3)return null;return {type:'Polygon',coordinates:[[...state.boundary.map(p=>[Number(p.lon),Number(p.lat)]),[Number(state.boundary[0].lon),Number(state.boundary[0].lat)]]]}}
function boundaryCapture(){if(state.fieldPoints.length<3)return toast('Capture at least 3 field points.');state.boundaryHistory.push(JSON.parse(JSON.stringify(state.boundary)));state.boundaryFuture=[];state.boundary=state.fieldPoints.map(p=>({lat:Number(p.lat),lon:Number(p.lon),source:p.source}));audit('Boundary closed from captured field points');persist();pages.field();toast('Boundary closed.')}
function undoBoundary(){if(!state.boundary.length)return toast('Nothing to undo.');state.boundaryFuture.push(JSON.parse(JSON.stringify(state.boundary)));state.boundary=state.boundaryHistory.pop()||[];persist();pages.field()}
function redoBoundary(){if(!state.boundaryFuture.length)return toast('Nothing to redo.');state.boundaryHistory.push(JSON.parse(JSON.stringify(state.boundary)));state.boundary=state.boundaryFuture.pop();persist();pages.field()}
function editBoundary(){if(state.boundary.length<3)return toast('Close a boundary first.');const rows=state.boundary.map((p,i)=>`<tr><td>${i+1}</td><td><input id="blat${i}" value="${p.lat}" type="number" step="0.0000001"></td><td><input id="blon${i}" value="${p.lon}" type="number" step="0.0000001"></td><td><button class="btn danger" onclick="deleteBoundaryVertex(${i})">Delete</button></td></tr>`).join('');const m=document.createElement('div');m.id='boundaryModal';m.className='modal-backdrop';m.innerHTML=`<div class="modal-card"><div class="card-head"><h2>Boundary Editor</h2><button class="btn" onclick="document.getElementById('boundaryModal').remove()">✕</button></div><div class="notice">Edit vertices, delete bad points, then save. This changes the working geometry only; original evidence remains in audit history.</div><table class="table"><thead><tr><th>#</th><th>Latitude</th><th>Longitude</th><th></th></tr></thead><tbody>${rows}</tbody></table><div class="actions" style="justify-content:flex-end"><button class="btn" onclick="addBoundaryVertex()">+ Add Vertex</button><button class="btn primary" onclick="saveBoundaryEdit()">Save Geometry</button></div></div>`;document.body.appendChild(m)}
function deleteBoundaryVertex(i){state.boundary.splice(i,1);editBoundary()}
function addBoundaryVertex(){if(!state.boundary.length)return toast('Capture a first point first.');const p=state.boundary.at(-1);state.boundary.push({lat:p.lat,lon:p.lon});editBoundary()}
function saveBoundaryEdit(){const b=state.boundary.map((p,i)=>({lat:Number(document.getElementById('blat'+i)?.value),lon:Number(document.getElementById('blon'+i)?.value),source:'Boundary editor'})).filter(p=>Number.isFinite(p.lat)&&Number.isFinite(p.lon));if(b.length<3)return toast('At least 3 valid vertices are required.');state.boundaryHistory.push(state.boundary);state.boundary=b;state.boundaryFuture=[];audit('Boundary edited by officer');persist();document.getElementById('boundaryModal')?.remove();pages.field();toast('Boundary geometry updated.')}
function computePaperGeoreference(){
 const pairs=[0,1,2].map(i=>({x:Number(document.getElementById('pgx'+i)?.value),y:Number(document.getElementById('pgy'+i)?.value),lon:Number(document.getElementById('pglon'+i)?.value),lat:Number(document.getElementById('pgllat'+i)?.value)}));
 if(pairs.some(p=>![p.x,p.y,p.lon,p.lat].every(Number.isFinite)))return toast('Fill all 3 control pairs.');
 const det=pairs[0].x*(pairs[1].y-pairs[2].y)+pairs[1].x*(pairs[2].y-pairs[0].y)+pairs[2].x*(pairs[0].y-pairs[1].y);if(Math.abs(det)<1e-12)return toast('Control points are collinear. Choose 3 non-collinear points.');
 const solve=(v)=>{const [p,q,r]=pairs;const D=p.x*(q.y-r.y)+q.x*(r.y-p.y)+r.x*(p.y-q.y);const A=(v[0]*(q.y-r.y)+v[1]*(r.y-p.y)+v[2]*(p.y-q.y))/D;const B=(p.x*(v[1]-v[2])+q.x*(v[2]-v[0])+r.x*(v[0]-v[1]))/D;const C=(p.x*(q.y*v[2]-r.y*v[1])+q.x*(r.y*v[0]-p.y*v[2])+r.x*(p.y*v[1]-q.y*v[0]))/D;return [A,B,C]};
 const lonT=solve(pairs.map(p=>p.lon)),latT=solve(pairs.map(p=>p.lat));const pred=(p,t)=>t[0]*p.x+t[1]*p.y+t[2];const residuals=pairs.map(p=>Math.hypot(pred(p,lonT)-p.lon,pred(p,latT)-p.lat));const rms=Math.sqrt(residuals.reduce((a,b)=>a+b*b,0)/residuals.length);state.paperGcpPairs=pairs;state.paperGeoref={lonT,latT,rms,computedAt:new Date().toISOString()};state.pending.push({type:'PAPER_GEOREFERENCE',pairs:3,rms});audit('Paper record affine georeference computed',{rms});persist();pages.change();toast('Paper georeference transform computed.')
}
function clearPaperGeoreference(){state.paperGcpPairs=[];state.paperGeoref=null;persist();pages.change();toast('Paper georeference cleared.')}
function paperPixelToCoordinate(x,y){if(!state.paperGeoref)return null;const t=state.paperGeoref;return {lon:t.lonT[0]*x+t.lonT[1]*y+t.lonT[2],lat:t.latT[0]*x+t.latT[1]*y+t.latT[2]}}
function compareLoadedGeometries(){if(!(state.changeGeos.recorded&&state.changeGeos.observed))return toast('Load both old and new geometries.');document.getElementById('changeResult').innerHTML=changeResultHtml();audit('Old vs New geometry comparison completed');persist()}
function nearestDistanceM(p,ring){const kx=111320*Math.cos(p[1]*Math.PI/180),ky=110540;let best=Infinity;for(const q of ring){const dx=(p[0]-q[0])*kx,dy=(p[1]-q[1])*ky;best=Math.min(best,Math.hypot(dx,dy))}return best}
function maxVertexDisplacement(a,b){const ar=realGeometrySummary(a)?.rings?.[0]||[],br=realGeometrySummary(b)?.rings?.[0]||[];if(!ar.length||!br.length)return null;return Math.max(...ar.map(p=>nearestDistanceM(p,br)),...br.map(p=>nearestDistanceM(p,ar)))}
function changeResultHtml(){const a=realGeometrySummary(state.changeGeos.recorded),b=realGeometrySummary(state.changeGeos.observed),d=a&&b?((Number(b.areaHa)-Number(a.areaHa))/Number(a.areaHa)*100):null,disp=maxVertexDisplacement(state.changeGeos.recorded,state.changeGeos.observed);return `<b>Source geometry comparison</b><br>Recorded / old area: ${a.areaHa} ha<br>Observed / new area: ${b.areaHa} ha<br>Area difference: ${d.toFixed(2)}%<br>Maximum nearest-vertex displacement: ${disp==null?'—':disp.toFixed(3)+' m'}<br><span class="muted">Spatial difference is a verification trigger, not a legal encroachment finding.</span>`}
async function loadChangeFile(event,kind){const f=event.target.files?.[0];if(!f)return;try{const geo=JSON.parse(await f.text());if(!geometryFromGeoJSON(geo))throw Error('No Polygon/MultiPolygon');state.changeGeos[kind]=geo;persist();audit(`${kind==='recorded'?'Recorded':'Observed'} geometry loaded: ${f.name}`);pages.change();toast(`${kind} geometry loaded.`)}catch(e){toast('Invalid GeoJSON: '+e.message)}}
async function loadRecordEvidence(event){const f=event.target.files?.[0];if(!f)return;const hash=await sha256File(f);state.recordEvidence={name:f.name,size:f.size,type:f.type,hash,time:new Date().toISOString()};audit('Old paper/record evidence uploaded: '+f.name,{sha256:hash});persist();pages.change();toast('Record evidence saved with SHA-256 hash.')}
async function sha256File(f){const buf=await f.arrayBuffer();const h=await crypto.subtle.digest('SHA-256',buf);return [...new Uint8Array(h)].map(b=>b.toString(16).padStart(2,'0')).join('')}
function capturePhoto(event){const f=event.target.files?.[0];if(!f)return;sha256File(f).then(hash=>{const rec={name:f.name,size:f.size,type:f.type,time:new Date().toISOString(),sha256:hash};state.photos.push(rec);state.pending.push({type:'PHOTO',...rec});audit('Field photo captured: '+f.name,{sha256:hash});persist();pages.field();toast('Photo evidence captured and hashed.')})}
function addNote(){const n=prompt('Field note');if(n?.trim()){state.notes.push({text:n.trim(),time:new Date().toISOString()});state.pending.push({type:'NOTE',text:n.trim()});audit('Field note added');persist();pages.field();toast('Field note saved.')}}
function finishParcel(){audit('Parcel '+state.selectedParcel+' submitted for officer verification');state.methodology[10]={status:'COMPLETE',date:new Date().toISOString(),officer:'SURVEY-001',source:'Field verification workflow',evidence:'Officer submission',accuracy:'—'};persist();go('evidence');toast('Parcel submitted for verification.')}
function verifyParcel(){state.methodology.verification={status:'COMPLETE',date:new Date().toISOString(),officer:'SURVEY-001',evidence:'Officer confirmation'};audit('Parcel '+state.selectedParcel+' verified by demo officer action');persist();go('twin');toast('Verification action recorded. This is a prototype officer action, not government certification.')}
function sendTwinVerification(){audit('Parcel '+state.selectedParcel+' sent for authorized officer verification');persist();toast('Verification task recorded.')}
function toggleOffline(){state.offline=!state.offline;audit(state.offline?'Offline capture enabled':'Online mode enabled');if(!state.offline&&state.pending.length){const n=state.pending.length;state.pending=[];persist();toast(`${n} queued records marked synchronized locally.`)}else{persist();renderShell()}}
function runPipeline(){const checks=[!!state.uavFile,!!state.uavMetadata||!!state.loadedGeoJson,!!state.uavFile,!!state.uavFile,!!state.loadedGeoJson,!!state.loadedGeoJson];checks.forEach((ok,i)=>{const e=document.getElementById('uavStage'+i);if(e){e.textContent=ok?'INPUT AVAILABLE':'WAITING';e.className='status '+(ok?'green':'amber')}});audit('UAV pipeline prerequisites validated');toast(checks.every(Boolean)?'All browser-verifiable UAV inputs are available.':'Some UAV inputs are still missing.')}
function uavStage(i){const c=[!!state.uavFile,!!state.uavMetadata||!!state.loadedGeoJson,!!state.uavFile,!!state.uavFile,!!state.loadedGeoJson,!!state.loadedGeoJson];return c[i]?'INPUT AVAILABLE':'WAITING'}
function acceptMethodStage(i,source){state.methodology[i]={status:'COMPLETE',date:new Date().toISOString(),officer:'SURVEY-001',source,evidence:source,accuracy:'—'};persist()}
function exportTwin(){const p=pagesCommonParcel(),payload={schemaVersion:'3.0',recordType:'Digital Parcel Twin',parcelId:p.id,projectId:state.activeProjectId||state.projects[0]?.id,referenceRecord:{areaHa:p.area,crop:p.crop,source:'Prototype register; not authenticated'},recordEvidence:state.recordEvidence,fieldObservations:state.fieldPoints,boundary:state.boundary,geometryAnalysis:state.geometryAnalysis,changeAnalysis:state.changeGeos,notes:state.notes,photos:state.photos,audit:state.audit,provenance:{authenticatedCadastralGeometry:false,liveFieldEvidence:state.fieldPoints.length>0,sourceEvidence:!!state.recordEvidence},generatedAt:new Date().toISOString()};downloadBlob(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),`kshetrasetu-parcel-${p.id}-twin.json`);audit('Digital Parcel Twin exported')}
function exportData(){const payload={schemaVersion:'3.0',project:state.projects[0],selectedParcel:state.selectedParcel,fieldPoints:state.fieldPoints,boundary:state.boundary,controlPoints:state.controlPoints,recordEvidence:state.recordEvidence,changeGeometries:state.changeGeos,methodology:state.methodology,audit:state.audit,notes:state.notes,photos:state.photos,provenance:'Prototype/local evidence only; no government authentication claimed.',generatedAt:new Date().toISOString()};downloadBlob(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),'kshetrasetu-survey-record.json');audit('Survey record exported')}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function boot(){login()}
boot();
